package work.tokenpro.client;

import javax.imageio.ImageIO;
import javax.swing.*;
import java.awt.*;
import java.io.ByteArrayInputStream;
import java.util.Base64;

final class OfficialIcons {
    private OfficialIcons() {}

    static Icon client(String name, int size) {
        String encoded = "Claude".equals(name) ? CLAUDE : CODEX;
        try {
            Image image = ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(encoded)));
            return new ImageIcon(image.getScaledInstance(size, size, Image.SCALE_SMOOTH));
        } catch (Exception e) { return null; }
    }

    private static final String CODEX = "";
    private static final String CLAUDE = "";
}

